CustomField.formula:
Text(Round(Digital_Completion_Percentage__c , 2)*100)&"% "&

/* Create an opening border of grey on the far left, 18 px high and 2 px wide */ 
IMAGE("/resource/1696023137000/incomplete?", "", 18, 2)
&
/* Create a green bar to represent completeness of the task, 18 px high and of a width of the % field value (1% = 1px) */
IMAGE("/resource/1696023102000/complete?", "Complete", 18,  Digital_Completion_Percentage__c * 200)
&
/* Create a grey bar to represent incompleteness of the task, 18 px high and of a width controlled by 1-% field value */
IMAGE("/resource/1696023137000/incomplete?", "Incomplete", 18, (1 -  Digital_Completion_Percentage__c ) * 200)
&
/* Create a closing border of grey on the far right, 18 pixels high and 2 px wide */ 
IMAGE("/resource/1696023137000/incomplete?", "", 18, 2)
